// 08 H8: Electron hardening (§6.5, [S1]). Permissions denied, navigation / window.open / webviews blocked, and the
// dev-server CSP header (incl. frame-ancestors) set only for the unpackaged dev server. Production relies on the
// meta CSP generated by build/vite-plugin-csp.ts and loads from file://.
import { isAppEntryUrl } from './ipc/router.js';
import type { TrustedOrigin } from './ipc/router.js';

/**
 * Header CSP for the dev server only (never packaged; see `applySessionPolicy`). Its main job is `frame-ancestors`,
 * which a meta CSP cannot carry.
 *
 * `'unsafe-inline'` in script-src is required in dev and is not a widening in practice: @vitejs/plugin-react injects
 * an inline React-Refresh preamble `<script type="module">` into index.html, and every CSP in force must allow it. This
 * static header cannot know that script's hash, so it allows inline scripts; the generated meta CSP
 * (build/vite-plugin-csp.ts) allows only that preamble's sha256 hash, and the browser enforces both policies, so the
 * effective dev policy admits exactly the hashed preamble. Production has no header CSP and its meta CSP is
 * `script-src 'self'` with no inline allowance.
 */
export const DEV_HEADER_CSP = [
  "default-src 'self'",
  "script-src 'self' 'unsafe-inline' http://localhost:*",
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' data:",
  "font-src 'self'",
  "connect-src 'self' ws://localhost:* http://localhost:*",
  "object-src 'none'",
  "base-uri 'none'",
  "form-action 'none'",
  "frame-ancestors 'none'",
].join('; ');

/** The part of `session` the policy touches. */
export interface SessionLike {
  setPermissionRequestHandler(handler: (wc: unknown, permission: string, cb: (granted: boolean) => void) => void): void;
  setPermissionCheckHandler(handler: () => boolean): void;
  webRequest: {
    onHeadersReceived(
      listener: (
        details: { url: string; responseHeaders?: Record<string, string[]> },
        cb: (r: { responseHeaders?: Record<string, string[]> }) => void,
      ) => void,
    ): void;
  };
}

/** Denies every permission; sets the dev CSP header for dev-server responses when unpackaged. */
export function applySessionPolicy(session: SessionLike, origin: TrustedOrigin): void {
  session.setPermissionRequestHandler((_wc, _permission, cb) => {
    cb(false);
  });
  session.setPermissionCheckHandler(() => false);
  const devUrl = origin.devServerUrl;
  if (origin.isPackaged || devUrl === undefined || devUrl === '') return;
  const devOrigin = new URL(devUrl).origin;
  session.webRequest.onHeadersReceived((details, cb) => {
    if (!details.url.startsWith(devOrigin)) {
      cb(details.responseHeaders === undefined ? {} : { responseHeaders: details.responseHeaders });
      return;
    }
    cb({ responseHeaders: { ...details.responseHeaders, 'Content-Security-Policy': [DEV_HEADER_CSP] } });
  });
}

/** The part of `WebContents` the guards touch. */
export interface WebContentsLike {
  on(event: 'will-navigate', l: (e: { preventDefault(): void }, url: string) => void): unknown;
  on(event: 'will-attach-webview', l: (e: { preventDefault(): void }) => void): unknown;
  setWindowOpenHandler(h: () => { action: 'deny' }): void;
}

/** Hardens one web contents: no navigation away from the app entry, no window.open, no webviews. */
export function guardWebContents(wc: WebContentsLike, origin: TrustedOrigin): void {
  wc.on('will-navigate', (e, url) => {
    if (!isAppEntryUrl(url, origin)) e.preventDefault();
  });
  wc.setWindowOpenHandler(() => ({ action: 'deny' }));
  wc.on('will-attach-webview', (e) => {
    e.preventDefault();
  });
}
